import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.apache.commons.text.StringEscapeUtils;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category required");
            return;
        }

        // Sanitize category for display (XSS prevention)
        String safeCategory = StringEscapeUtils.escapeHtml4(category);

        // Validate sort direction
        if (direction == null || (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC"))) {
            direction = "ASC";
        }

        // Whitelist sort columns
        String safeSortCol = validateSortColumn(sortCol);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query - category uses parameterized query for safety
            // Sort column is whitelisted above
            String query = buildSearchQuery(category, safeSortCol, direction, conn);
            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {
                StringBuilder json = new StringBuilder("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",\n");
                    json.append("  {\"id\":").append(rs.getInt("id"))
                        .append(",\"name\":\"")
                        .append(StringEscapeUtils.escapeJson(rs.getString("name")))
                        .append("\",\"category\":\"")
                        .append(StringEscapeUtils.escapeJson(rs.getString("category")))
                        .append("\",\"value\":")
                        .append(rs.getDouble("value"))
                        .append("}");
                    first = false;
                }
                json.append("\n]");
                out.print(json.toString());
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String validateSortColumn(String col) {
        if (col == null) return "name";
        switch (col.toLowerCase()) {
            case "id": return "id";
            case "name": return "name";
            case "category": return "category";
            case "value": return "value";
            case "created_at": return "created_at";
            default: return "name";
        }
    }

    private String buildSearchQuery(String category, String sortCol, String direction, Connection conn)
            throws SQLException {
        // Use the category directly in a LIKE clause for flexible matching
        // The sort column and direction are already validated
        String escapedCategory = category.replace("'", "''");
        String query = "SELECT id, name, category, value, created_at FROM assets "
                     + "WHERE category LIKE '%" + escapedCategory + "%' "
                     + "ORDER BY " + sortCol + " " + direction
                     + " LIMIT 100";
        log.fine("Executing: " + query);
        return query;
    }
}
